        if extra:
            has_extra += 1
    except Exception:
        pass
print('Total instances:', total)
print('Has connected-not-gold:', has_extra)
if total != 0:
    print('Z%% = %.1f%%' % (has_extra/total*100))
else:
    print('NO DATA')
